-- Removing the final older current cohort satisfies its bucket invalidation.
-- Keep the work clock/frontier intact; newer signals must still requeue.
DROP TRIGGER inventory_matching_bucket_job_progress;
CREATE TRIGGER inventory_matching_bucket_job_progress BEFORE UPDATE ON inventory_matching_bucket_jobs WHEN NEW.work_version=OLD.work_version AND (NEW.completed_version!=OLD.completed_version OR NEW.cursor_version!=OLD.cursor_version OR NEW.cursor_set!=OLD.cursor_set) AND NOT(NEW.completed_version=OLD.work_version AND OLD.completed_version<OLD.work_version AND (NEW.cursor_version,NEW.cursor_set)=(OLD.cursor_version,OLD.cursor_set) AND NOT EXISTS(SELECT 1 FROM inventory_matching_bucket_dependents d INDEXED BY inventory_matching_bucket_dependents_cursor WHERE d.tenant=OLD.tenant AND d.generation_id=OLD.generation_id AND d.scope_id=OLD.scope_id AND d.key_class=OLD.key_class AND d.bucket_hash=OLD.bucket_hash AND d.seen_version<OLD.work_version)) BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_bucket_pages p JOIN inventory_matching_bucket_guards g ON g.tenant=p.tenant AND g.page_id=p.page_id WHERE p.tenant=OLD.tenant AND p.generation_id=OLD.generation_id AND p.scope_id=OLD.scope_id AND p.key_class=OLD.key_class AND p.bucket_hash=OLD.bucket_hash AND p.state='prepared' AND p.work_version=OLD.work_version AND p.completed_version=OLD.completed_version AND p.previous_version=OLD.cursor_version AND p.previous_set=OLD.cursor_set AND p.next_version=NEW.cursor_version AND p.next_set=NEW.cursor_set AND NEW.completed_version=CASE p.complete WHEN 1 THEN p.work_version ELSE p.completed_version END AND NOT EXISTS(SELECT 1 FROM inventory_matching_bucket_stale_authority x WHERE x.tenant=p.tenant AND x.page_id=p.page_id)) THEN RAISE(ABORT,'inventory matching bucket progress guard missing') END;
END;
CREATE TRIGGER inventory_matching_bucket_observed AFTER DELETE ON inventory_matching_bucket_dependents BEGIN
 UPDATE inventory_matching_bucket_jobs SET completed_version=work_version
 WHERE tenant=OLD.tenant AND generation_id=OLD.generation_id AND scope_id=OLD.scope_id AND key_class=OLD.key_class AND bucket_hash=OLD.bucket_hash AND completed_version<work_version
 AND NOT EXISTS(SELECT 1 FROM inventory_matching_bucket_dependents d INDEXED BY inventory_matching_bucket_dependents_cursor WHERE d.tenant=OLD.tenant AND d.generation_id=OLD.generation_id AND d.scope_id=OLD.scope_id AND d.key_class=OLD.key_class AND d.bucket_hash=OLD.bucket_hash AND d.seen_version<inventory_matching_bucket_jobs.work_version);
END;
